    custom_key_description = {
        en = "The service's key. Leave it empty and the API key field above is used instead, so the pre-filled DeepL defaults run without pasting the same key twice. Substituted wherever {key} appears - in the auth header, the request template or the query template. Note that 'restore defaults' clears a key field (there is no default for one), while the rest of this page comes back as DeepL's parameters.",
        ["zh-cn"] = "服务的密钥。留空则改用上面的「API 密钥」字段，这样预填的 DeepL 参数不用再粘一次密钥。它会被填到出现 {key} 的地方——鉴权头、请求参数模板或查询模板。「恢复默认」会把密钥字段清空（密钥没有默认值），而本页其它字段都会恢复成 DeepL 的参数。",
        ["zh-tw"] = "服務的金鑰。留空時會改用上方的 API 金鑰欄位，因此預先填入的 DeepL 預設值不必重複貼上同一把金鑰。凡是出現 {key} 的地方都會被取代——驗證標頭、請求範本或查詢範本。請注意，「恢復預設值」會清空金鑰欄位（金鑰沒有預設值），而本頁其餘部分都會還原成 DeepL 的參數。",
        ["ja"] = "サービスのキーです。空にすると上の API キー欄が代わりに使われるため、あらかじめ入力された DeepL の初期値でも同じキーを二度貼り付ける必要はありません。{key} が現れる場所（認証ヘッダー、リクエストテンプレート、クエリテンプレート）で置き換えられます。「デフォルトに戻す」はキー欄を空にします（キーには初期値がないため）が、このページの他の項目は DeepL のパラメータに戻ります。",
        ["ko"] = "서비스의 키입니다. 비워 두면 위의 API 키 필드가 대신 사용되므로, 미리 채워진 DeepL 기본값을 쓸 때 같은 키를 두 번 붙여 넣지 않아도 됩니다. {key}가 나타나는 곳마다 치환됩니다. 인증 헤더, 요청 템플릿, 쿼리 템플릿 모두 해당됩니다. 참고로 '기본값 복원'은 키 필드를 비웁니다(키에는 기본값이 없습니다). 이 페이지의 나머지 항목은 DeepL의 매개변수로 되돌아옵니다.",
        ["ru"] = "Ключ сервиса. Оставьте поле пустым — тогда используется поле «Ключ API» выше, так что предзаполненные параметры DeepL работают без повторной вставки того же ключа. Подставляется всюду, где встречается {key}, — в заголовок авторизации, шаблон тела запроса или шаблон строки запроса. Учтите, что «восстановить значения по умолчанию» очищает поле ключа (значения по умолчанию для него нет), а остальные поля этой страницы возвращаются к параметрам DeepL.",
        ["de"] = "Der Schlüssel des Dienstes. Bleibt er leer, wird stattdessen das API-Schlüsselfeld oben verwendet, damit die vorbelegten DeepL-Standardwerte ohne ein zweites Einfügen desselben Schlüssels laufen. Er wird überall eingesetzt, wo {key} steht - im Auth-Header, in der Anfrage-Vorlage oder in der Query-Vorlage. Beachte, dass „Standard wiederherstellen“ ein Schlüsselfeld leert (für einen Schlüssel gibt es keinen Standardwert), während der Rest dieser Seite als DeepLs Parameter zurückkommt.",
        ["fr"] = "La clé du service. Laissez-la vide pour utiliser à la place le champ clé API ci-dessus, afin que les valeurs DeepL pré-remplies fonctionnent sans coller deux fois la même clé. Elle est substituée partout où {key} apparaît — dans l'en-tête d'authentification, le modèle de corps ou le modèle de requête (GET). À noter : «  restaurer les valeurs par défaut » vide un champ de clé (il n'y a pas de valeur par défaut pour une clé), tandis que le reste de cette page revient aux paramètres de DeepL.",
        ["es"] = "La clave del servicio. Déjala vacía y se usará en su lugar el campo clave de API de arriba, de modo que los valores de DeepL ya rellenados funcionan sin pegar la misma clave dos veces. Se sustituye allí donde aparezca {key}: en la cabecera de autenticación, la plantilla de petición o la plantilla de consulta. Ten en cuenta que «restaurar los valores predeterminados» vacía un campo de clave (no hay valor predeterminado para una), mientras que el resto de esta página vuelve a los parámetros de DeepL.",
        ["it"] = "La chiave del servizio. Lasciala vuota e viene usato il campo chiave API qui sopra, così i valori predefiniti di DeepL già inseriti funzionano senza incollare due volte la stessa chiave. Viene sostituita ovunque compaia {key}: nell'intestazione di autenticazione, nel modello di richiesta o nel modello di query. Nota che «ripristina i valori predefiniti» svuota il campo della chiave (per essa non esiste un valore predefinito), mentre il resto di questa pagina torna ai parametri di DeepL.",
        ["pl"] = "Klucz usługi. Pozostaw go pustego, a zamiast niego zostanie użyte pole „Klucz API” powyżej — dzięki temu wstępnie wypełnione ustawienia DeepL działają bez wklejania tego samego klucza dwa razy. Podstawiany wszędzie tam, gdzie występuje {key} — w nagłówku autoryzacji, szablonie żądania lub szablonie zapytania. Uwaga: „przywróć domyślne” czyści pole klucza (nie ma dla niego wartości domyślnej), natomiast reszta tej strony wraca do parametrów DeepL.",
        ["pt-br"] = "A chave do serviço. Deixe em branco para usar o campo de chave de API acima, assim os padrões do DeepL já preenchidos funcionam sem colar a mesma chave duas vezes. Substituída onde {key} aparecer — no cabeçalho de autenticação, no modelo de requisição ou no modelo de consulta. Observe que “Restaurar padrões” limpa um campo de chave (não existe padrão para ele), enquanto o resto desta página volta aos parâmetros do DeepL.",
    },
