    custom_langs_description = {
        en = "How your service spells the languages, one 'code=SERVICE_CODE' per entry, separated by ';;' or a literal \n. The mod's codes are the game's (en, zh-cn, zh-tw, pt-br). Ships with DeepL's spelling of all of them (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Careful: the same mapping is used for the source and the target, and DeepL refuses the regional variants as a *source* language - 'en=EN-US' makes every request fail with 'source_lang not supported', so the English entry has to be 'en=EN'. Google wants 'zh-tw=zh-TW', Baidu 'zh-tw=cht'.",
        ["zh-cn"] = "你的服务怎么写语言，每项 '代码=服务代码'，用 ';;' 或字面量 \n 分隔。本 mod 用的是游戏的语言码（en、zh-cn、zh-tw、pt-br）。默认已填好 DeepL 的全部写法（zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR……）。注意：同一份映射既当源语言也当目标语言，而 DeepL 不接受带地区后缀的写法作为**源**语言——写成 'en=EN-US' 会让每次请求都以 'source_lang not supported' 失败，所以英语必须是 'en=EN'。Google 要 'zh-tw=zh-TW'，百度要 'zh-tw=cht'。",
        ["zh-tw"] = "你的服務如何拼寫語言，每項為 '代碼=服務代碼'，以 ';;' 或字面上的 \n 分隔。本模組使用的代碼就是遊戲的代碼（en、zh-cn、zh-tw、pt-br）。出廠時已附上 DeepL 對所有語言的拼法（zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...）。請注意：同一份對應同時用於來源語言與目標語言，而 DeepL 不接受帶地區變體的寫法作為*來源*語言——'en=EN-US' 會讓每次請求都以 'source_lang not supported' 失敗，因此英文項目必須是 'en=EN'。Google 要 'zh-tw=zh-TW'，百度要 'zh-tw=cht'。",
        ["ja"] = "サービスが言語をどう表記するかを指定します。1 項目につき「code=SERVICE_CODE」を 1 つ、「;;」または文字列としての \n で区切ります。本モッドのコードはゲームのもの（en、zh-cn、zh-tw、pt-br）です。初期値には DeepL の表記がすべて入っています（zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...）。注意：同じマッピングが原文と訳文の両方に使われ、DeepL は地域変種を*原文*言語として受け付けません。「en=EN-US」とするとすべてのリクエストが「source_lang not supported」で失敗するため、英語は「en=EN」でなければなりません。Google は「zh-tw=zh-TW」、Baidu は「zh-tw=cht」です。",
        ["ko"] = "서비스에서 언어를 어떻게 표기하는지 지정합니다. 항목당 '코드=SERVICE_CODE' 하나씩, ';;' 또는 실제 줄바꿈(\n)으로 구분합니다. 이 모드의 코드는 게임의 언어 코드(en, zh-cn, zh-tw, pt-br)입니다. 기본값에는 DeepL 표기가 모두 들어 있습니다(zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). 주의: 같은 매핑을 원본 언어와 대상 언어에 함께 사용하며, DeepL은 지역 변형 표기를 *원본* 언어로 거부합니다. 'en=EN-US'라고 쓰면 모든 요청이 'source_lang not supported'로 실패하므로 영어 항목은 반드시 'en=EN'이어야 합니다. Google은 'zh-tw=zh-TW', Baidu는 'zh-tw=cht'를 요구합니다.",
        ["ru"] = "Как ваш сервис записывает языки: по одной записи 'код=КОД_СЕРВИСА', разделённых ';;' или литеральным \n. Коды мода — это коды игры (en, zh-cn, zh-tw, pt-br). По умолчанию подставлена запись DeepL для всех них (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Осторожно: одно и то же сопоставление используется и для исходного, и для целевого языка, а DeepL не принимает региональные варианты в качестве *исходного* языка — из-за 'en=EN-US' каждый запрос будет падать с 'source_lang not supported', поэтому для английского должно быть 'en=EN'. Google хочет 'zh-tw=zh-TW', Baidu — 'zh-tw=cht'.",
        ["de"] = "Wie dein Dienst die Sprachen schreibt: ein 'code=SERVICE_CODE' pro Eintrag, getrennt durch ';;' oder ein literales \n. Die Codes des Mods entsprechen denen des Spiels (en, zh-cn, zh-tw, pt-br). Vorbelegt mit DeepLs Schreibweise für alle (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Achtung: Dieselbe Zuordnung wird für die Quell- und die Zielsprache verwendet, und DeepL lehnt die regionalen Varianten als *Quell*sprache ab - 'en=EN-US' lässt jede Anfrage mit 'source_lang not supported' fehlschlagen, der englische Eintrag muss also 'en=EN' sein. Google will 'zh-tw=zh-TW', Baidu 'zh-tw=cht'.",
        ["fr"] = "La façon dont votre service écrit les langues, une entrée 'code=CODE_SERVICE' par ligne, séparées par ';;' ou par un \n littéral. Les codes du mod sont ceux du jeu (en, zh-cn, zh-tw, pt-br). Livré avec l'écriture DeepL de toutes ces langues (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Attention : la même correspondance sert pour la langue source et la langue cible, et DeepL refuse les variantes régionales comme langue *source* — 'en=EN-US' fait échouer chaque requête avec 'source_lang not supported', l'entrée anglaise doit donc être 'en=EN'. Google attend 'zh-tw=zh-TW', Baidu 'zh-tw=cht'.",
        ["es"] = "Cómo escribe tu servicio los idiomas, una entrada «code=SERVICE_CODE» por elemento, separadas por «;;» o por un \n literal. Los códigos del mod son los del juego (en, zh-cn, zh-tw, pt-br). Viene con la grafía de DeepL para todos ellos (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Cuidado: la misma correspondencia se usa para el idioma de origen y el de destino, y DeepL rechaza las variantes regionales como idioma *de origen*: «en=EN-US» hace que todas las peticiones fallen con «source_lang not supported», así que la entrada del inglés tiene que ser «en=EN». Google quiere «zh-tw=zh-TW», Baidu «zh-tw=cht».",
        ["it"] = "Come il tuo servizio scrive le lingue, una voce «codice=CODICE_SERVIZIO» per riga, separate da «;;» o da un \n letterale. I codici della mod sono quelli del gioco (en, zh-cn, zh-tw, pt-br). È preimpostato con la grafia di DeepL per tutte (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Attenzione: la stessa mappatura vale sia per la lingua di partenza sia per quella di destinazione, e DeepL rifiuta le varianti regionali come lingua di *partenza*: «en=EN-US» fa fallire ogni richiesta con «source_lang not supported», quindi la voce inglese deve essere «en=EN». Google vuole «zh-tw=zh-TW», Baidu «zh-tw=cht».",
        ["pl"] = "Jak twoja usługa zapisuje języki — jedna pozycja „code=SERVICE_CODE”, oddzielone „;;” lub dosłownym \n. Kody moda to kody gry (en, zh-cn, zh-tw, pt-br). Domyślnie zawiera zapis DeepL dla wszystkich z nich (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Uwaga: to samo mapowanie służy zarówno językowi źródłowemu, jak i docelowemu, a DeepL odrzuca warianty regionalne jako język *źródłowy* — „en=EN-US” sprawia, że każde żądanie kończy się błędem „source_lang not supported”, więc wpis dla angielskiego musi brzmieć „en=EN”. Google oczekuje „zh-tw=zh-TW”, Baidu „zh-tw=cht”.",
        ["pt-br"] = "Como o seu serviço escreve os idiomas, uma entrada “code=SERVICE_CODE” por item, separadas por “;;” ou por um \n literal. Os códigos do mod são os do jogo (en, zh-cn, zh-tw, pt-br). Já vem com a grafia do DeepL para todos eles (zh-cn=ZH-HANS;; zh-tw=ZH-HANT;; pt-br=PT-BR ...). Atenção: o mesmo mapeamento é usado para a origem e o destino, e o DeepL recusa as variantes regionais como idioma de *origem* — “en=EN-US” faz toda requisição falhar com “source_lang not supported”, então a entrada do inglês precisa ser “en=EN”. O Google quer “zh-tw=zh-TW”, o Baidu quer “zh-tw=cht”.",
    },
